/* DUS Deneme 1 — 120 soru. Sıra: Temel 1-40 (Anatomi 6, Histoloji-Embriyoloji 4, Fizyoloji 6, Biyokimya 6, Mikrobiyoloji 6, Patoloji 4, Farmakoloji 4, Tıbbi Biyoloji-Genetik 4), Klinik 41-120 (Restoratif, Protetik, Cerrahi, Radyoloji, Periodontoloji, Ortodonti, Endodonti, Çocuk; 10ar soru). */
window.DENEME={
no:1,
baslik:"DUS Deneme 1",
tarih:"2026-10-14",
aciklama:"26 Nisan 2026 sınavının dağılımına göre hazırlanan ilk deneme.",
Q:[
/* ===== ANATOMİ ===== */
{t:"vaka",q:"Gömülü alt sağ üçüncü molar dişi çekilen bir hastada, işlem sonrasında n. lingualis'in hasar gördüğü tespit ediliyor.<br><br><b>Bu hastada aşağıdakilerden hangisinin görülmesi <u>en az olasıdır</u>?</b>",o:["Dilin sağ ön 2/3'ünde dokunma duyusu kaybı","Dilin sağ ön 2/3'ünde tat duyusu kaybı","Ağız tabanının sağ yarısında duyu kaybı","Sağ alt lingual dişetinde duyu kaybı","Dilin sağ arka 1/3'ünde tat duyusu kaybı"],a:"E",e:"N. lingualis (V3) dilin ön 2/3'ünün genel duyusunu taşır; chorda tympani lifleri (VII) onunla seyrederek ön 2/3'ün tat duyusunu iletir. Ağız tabanı ve lingual dişeti de n. lingualis ile innerve olur. Dilin arka 1/3'ünün tat ve genel duyusu n. glossopharyngeus (IX) ile taşındığından etkilenmez."},
{t:"eslestirme",q:"Aşağıdaki yapı ile kafa tabanında içinden geçtiği delik eşleştirmelerinden hangisi doğrudur?",o:["N. maxillaris – Foramen ovale","N. mandibularis – Foramen rotundum","A. meningea media – Foramen spinosum","N. glossopharyngeus – Canalis nervi hypoglossi","N. petrosus major – Foramen stylomastoideum"],a:"C",e:"V2 foramen rotundum'dan, V3 foramen ovale'den geçer. A. meningea media foramen spinosum'dan kafa boşluğuna girer. IX, X ve XI foramen jugulare'den çıkar. Foramen stylomastoideum'dan n. facialis çıkar; n. petrosus major ise hiatus canalis n. petrosi majoris'ten çıkıp foramen lacerum bölgesine uzanır."},
{t:"olumsuz",q:"Aşağıdaki kaslardan hangisi n. facialis tarafından innerve <u>edilmez</u>?",o:["M. buccinator","M. stylohyoideus","Venter posterior m. digastrici","M. tensor veli palatini","M. stapedius"],a:"D",e:"M. tensor veli palatini, n. mandibularis'in (V3) dalı olan n. pterygoideus medialis'ten innerve olur; yumuşak damağın V3 ile innerve olan tek kasıdır. Diğer seçeneklerdeki kaslar 2. faringeal ark türevi olup n. facialis tarafından innerve edilir."},
{t:"vaka",q:"Nörolojik muayenede dilini dışarı çıkarması istenen bir hastanın dilinin sağa saptığı ve dilin sağ yarısında atrofi geliştiği gözleniyor.<br><br><b>Bu bulgulardan sorumlu olması <u>en olası</u> lezyon aşağıdakilerden hangisidir?</b>",o:["Sol n. hypoglossus hasarı","Sağ n. hypoglossus hasarı","Sağ n. lingualis hasarı","Sol n. glossopharyngeus hasarı","Sağ n. vagus hasarı"],a:"B",e:"Dili öne çıkaran m. genioglossus'tur. Bir taraftaki n. hypoglossus (alt motor nöron) hasarında sağlam taraftaki genioglossus dili karşıya iter; dil lezyon tarafına sapar ve aynı tarafta atrofi ile fasikülasyon görülür."},
{t:"oncullu",r:["Foramen rotundum aracılığıyla fossa cranii media ile bağlantılıdır.","Fissura orbitalis inferior aracılığıyla orbita ile bağlantılıdır.","Foramen sphenopalatinum aracılığıyla cavitas nasi ile bağlantılıdır."],q:"Fossa pterygopalatina ile ilgili yukarıdaki ifadelerden hangileri doğrudur?",o:["I, II ve III","Yalnız I","I ve II","II ve III","Yalnız III"],a:"A",e:"Üç ifade de doğrudur. Fossa pterygopalatina ayrıca canalis pterygoideus ile foramen lacerum bölgesine, canalis palatinus major ile ağız boşluğuna, fissura pterygomaxillaris ile fossa infratemporalis'e açılır. İçinde ganglion pterygopalatinum, V2 ve a. maxillaris'in üçüncü bölümü bulunur."},
{t:"bilgi",q:"Larinksin iç kaslarından hangisi rima glottidis'i açan (abdüksiyon yaptıran) tek kastır?",o:["M. cricothyroideus","M. cricoarytenoideus lateralis","M. arytenoideus transversus","M. thyroarytenoideus","M. cricoarytenoideus posterior"],a:"E",e:"M. cricoarytenoideus posterior, processus muscularis'i geriye çekerek processus vocalis'leri laterale döndürür ve rima glottidis'i açar. N. laryngeus recurrens ile innerve olur; iki taraflı hasarda hava yolu tıkanabilir. M. cricothyroideus (n. laryngeus superior, ramus externus) ses tellerini gerer."},
/* ===== HİSTOLOJİ-EMBRİYOLOJİ ===== */
{t:"bilgi",q:"Kök gelişimini yönlendiren Hertwig epitelyal kök kını aşağıdaki tabakalardan hangilerinin birleşmesiyle oluşur?",o:["İç mine epiteli ve stratum intermedium","Dış mine epiteli ve stellat retikulum","İç ve dış mine epiteli","Stratum intermedium ve stellat retikulum","Dental papilla ve dental folikül"],a:"C",e:"Servikal halkada iç ve dış mine epiteli, arada stratum intermedium ve stellat retikulum olmadan birleşerek Hertwig kök kınını oluşturur. Kök kını odontoblast farklılaşmasını indükler; parçalandıktan sonra kalıntıları PDL içinde Malassez epitel artıkları olarak kalır."},
{t:"olumsuz",q:"Aşağıdakilerden hangisi birinci faringeal arkın türevlerinden biri <u>değildir</u>?",o:["Malleus","M. stylohyoideus","M. masseter","M. tensor tympani","Venter anterior m. digastrici"],a:"B",e:"1. ark (mandibuler ark) türevleri: Meckel kıkırdağından malleus ve incus, çiğneme kasları, m. mylohyoideus, venter anterior m. digastrici, m. tensor tympani ve m. tensor veli palatini; siniri V3'tür. M. stylohyoideus, stapes ve processus styloideus 2. ark (n. facialis) türevleridir."},
{t:"bilgi",q:"Odontoblastların dentin tübülleri içine uzanan sitoplazmik uzantılarına ne ad verilir?",o:["Tomes çıkıntısı","Korff lifleri","Sharpey lifleri","Tomes lifi","Retzius çizgileri"],a:"D",e:"Tomes lifi (odontoblastik uzantı) dentin tübülü içinde yer alır. Tomes çıkıntısı ise ameloblastın mine prizmasını şekillendiren apikal uzantısıdır; sınavda sık karıştırılır. Korff lifleri manto dentindeki kollajen demetleri, Sharpey lifleri sement ve kemiğe gömülü PDL lifleri, Retzius çizgileri minedeki büyüme çizgileridir."},
{t:"oncullu",r:["Sert damak","Yapışık dişeti","Yumuşak damak"],q:"Yukarıdaki bölgelerden hangileri keratinize çiğneme mukozası ile örtülüdür?",o:["I ve II","Yalnız I","Yalnız III","II ve III","I, II ve III"],a:"A",e:"Ağız mukozası üçe ayrılır: çiğneme mukozası (sert damak, yapışık dişeti; orto/parakeratinize), örtücü mukoza (dudak ve yanak iç yüzü, ağız tabanı, dilin alt yüzü, yumuşak damak, alveoler mukoza; nonkeratinize) ve özelleşmiş mukoza (dil sırtı)."},
/* ===== FİZYOLOJİ ===== */
{t:"bilgi",q:"Ventrikül kas hücrelerinde aksiyon potansiyelinin plato fazından en çok sorumlu iyon akımı aşağıdakilerden hangisidir?",o:["Voltaj kapılı hızlı Na⁺ kanallarından içe akım","L tipi voltaj kapılı Ca²⁺ kanallarından içe akım","İçe doğru düzeltici K⁺ akımı","T tipi Ca²⁺ kanallarından içe akım","Hiperpolarizasyonla aktive olan katyon (I<sub>f</sub>) akımı"],a:"B",e:"Faz 0 hızlı Na⁺ girişi, faz 2 (plato) L tipi Ca²⁺ girişinin gecikmiş K⁺ çıkışıyla dengelenmesi, faz 3 K⁺ çıkışıyla repolarizasyondur. I<sub>f</sub> (funny) akımı ve T tipi Ca²⁺ kanalları pacemaker hücrelerinde diyastolik depolarizasyondan sorumludur."},
{t:"olumsuz",q:"Aşağıdakilerden hangisi aldosteronun etkilerinden biri <u>değildir</u>?",o:["Toplayıcı kanalda Na⁺ geri emiliminin artması","Toplayıcı kanalda K⁺ salgısının artması","İnterkalar hücrelerden H⁺ salgısının artması","Tükürük bezi kanallarında Na⁺ geri emiliminin artması","Toplayıcı kanalda akuaporin-2 ekspresyonunu artırarak serbest su geri emilimini sağlaması"],a:"E",e:"Akuaporin-2'nin apikal membrana yerleştirilmesi ADH'nin (V2 reseptörü) etkisidir. Aldosteron ENaC ve Na⁺/K⁺-ATPaz ekspresyonunu artırır; Na⁺ geri emilimi, K⁺ ve H⁺ salgısı artar. Tükürük bezi, ter bezi ve kolonda da Na⁺ tutulumunu artırır."},
{t:"bilgi",q:"Aşağıdakilerden hangisi oksijen-hemoglobin disosiasyon eğrisini sağa kaydırır?",o:["Kanda PCO₂ artışı","Vücut sıcaklığının düşmesi","Eritrositte 2,3-BPG'nin azalması","Kan pH'sının yükselmesi","Fetal hemoglobin oranının artması"],a:"A",e:"Sağa kayma hemoglobinin O₂ afinitesinin azalması demektir: PCO₂ artışı, H⁺ artışı (pH düşüşü, Bohr etkisi), sıcaklık artışı, 2,3-BPG artışı ve egzersiz. HbF 2,3-BPG'yi zayıf bağladığı için eğriyi sola kaydırır."},
{t:"oncullu",r:["Gastrin","Histamin","Somatostatin","Asetilkolin"],q:"Yukarıdakilerden hangileri mide paryetal hücrelerinden asit salgısını artırır?",o:["I ve II","II ve III","I, II ve IV","I, III ve IV","Yalnız IV"],a:"C",e:"Asetilkolin (M3), gastrin (CCK-B) ve histamin (H2) asit salgısını artırır; histamin cAMP, diğer ikisi Ca²⁺ aracılığıyla etki eder. Somatostatin (D hücreleri) gastrin ve asit salgısını inhibe eder."},
{t:"bilgi",q:"Miyelinli sinir liflerinde sıçrayıcı (saltatorik) iletim için gerekli voltaj kapılı Na⁺ kanallarının yoğunlaştığı bölge aşağıdakilerden hangisidir?",o:["Ranvier boğumları","İnternodal bölge","Schwann hücresi gövdesi","Dendritler","Sinaptik veziküller"],a:"A",e:"Miyelin internodal bölgede kapasitansı azaltıp membran direncini artırır. Aksiyon potansiyeli Na⁺ kanallarının yoğun olduğu Ranvier boğumlarında yeniden oluşur ve boğumdan boğuma atlar; iletim hızı artar, enerji tüketimi azalır."},
{t:"bilgi",q:"İskelet kasında kasılmayı başlatmak üzere sarkoplazmik retikulumdan salınan Ca²⁺ iyonlarının bağlandığı protein aşağıdakilerden hangisidir?",o:["Tropomiyozin","Troponin I","Troponin T","Troponin C","Kalmodulin"],a:"D",e:"Ca²⁺ troponin C'ye bağlanır ve tropomiyozin aktin üzerindeki miyozin bağlanma bölgelerinden çekilir. Troponin I aktin-miyozin etkileşimini inhibe eder, troponin T tropomiyozine bağlanır. Düz kasta Ca²⁺ kalmoduline bağlanarak miyozin hafif zincir kinazını aktive eder."},
/* ===== BİYOKİMYA ===== */
{t:"vaka",q:"Dişeti kanaması, yara iyileşmesinde gecikme ve perifolliküler hemorajiler görülen bir hastada kollajen sentezinde prolin ve lizin kalıntılarının hidroksilasyonunun bozulduğu düşünülüyor.<br><br><b>Bu hastada eksikliği <u>en olası</u> vitamin aşağıdakilerden hangisidir?</b>",o:["Tiamin","Retinol","Kolekalsiferol","Fillokinon","Askorbik asit"],a:"E",e:"Prolil ve lizil hidroksilazlar kofaktör olarak askorbik asit (C vitamini) ve Fe²⁺ kullanır. Eksiklikte tropokollajen sarmalı stabil olmaz ve skorbüt gelişir: dişeti büyümesi ve kanaması, diş mobilitesi, perifolliküler hemoraji."},
{t:"bilgi",q:"Glikolizde substrat düzeyinde fosforilasyon ile ATP üreten ve fruktoz-1,6-bisfosfat ile ileri beslemeli (feed-forward) olarak aktive edilen enzim aşağıdakilerden hangisidir?",o:["Hekzokinaz","Fosfofruktokinaz-1","Pirüvat kinaz","Gliseraldehit-3-fosfat dehidrogenaz","Aldolaz"],a:"C",e:"Glikolizde substrat düzeyinde ATP üreten iki enzim fosfogliserat kinaz ve pirüvat kinazdır. Pirüvat kinaz fruktoz-1,6-bisfosfat ile ileri beslemeli aktive olur; ATP, alanin ve glukagon (fosforilasyon yoluyla) ile inhibe edilir."},
{t:"eslestirme",q:"Aşağıdaki metabolik yol – hız kısıtlayıcı enzim eşleştirmelerinden hangisi <u>yanlıştır</u>?",o:["Üre döngüsü – Arjinaz","Glikoliz – Fosfofruktokinaz-1","Glukoneogenez – Fruktoz-1,6-bisfosfataz","Kolesterol sentezi – HMG-KoA redüktaz","Yağ asidi sentezi – Asetil-KoA karboksilaz"],a:"A",e:"Üre döngüsünün hız kısıtlayıcı enzimi mitokondriyal karbamoil fosfat sentetaz I'dir; zorunlu aktivatörü N-asetilglutamattır. Arjinaz döngünün son basamağında arjininden üreyi açığa çıkarır."},
{t:"bilgi",q:"Hem sentezinin ilk ve hız kısıtlayıcı basamağını katalizleyen enzim ile bu basamağın gerçekleştiği hücre bölümü aşağıdakilerin hangisinde birlikte verilmiştir?",o:["ALA dehidrataz – Sitozol","Ferroşelataz – Mitokondri","Porfobilinojen deaminaz – Sitozol","ALA sentaz – Mitokondri","ALA sentaz – Sitozol"],a:"D",e:"Glisin + süksinil-KoA → δ-ALA tepkimesi mitokondride ALA sentaz ile (kofaktör B6) gerçekleşir ve hem tarafından feedback inhibe edilir. Ara basamaklar sitozolde, son basamak (Fe²⁺ eklenmesi, ferroşelataz) yine mitokondridedir. Kurşun ALA dehidrataz ve ferroşelatazı inhibe eder."},
{t:"bilgi",q:"Klasik fenilketonüride eksik olan enzim aşağıdakilerden hangisidir?",o:["Tirozinaz","Fenilalanin hidroksilaz","Homojentisat oksidaz","Fumarilasetoasetat hidrolaz","Sistatyonin β-sentaz"],a:"B",e:"Fenilalanin hidroksilaz (kofaktör BH4) eksikliğinde fenilalanin tirozine dönüşemez ve tirozin esansiyel hale gelir. Tirozinaz eksikliği albinizm, homojentisat oksidaz eksikliği alkaptonüri, fumarilasetoasetat hidrolaz eksikliği tip 1 tirozinemi, sistatyonin β-sentaz eksikliği homosistinüri yapar."},
{t:"oncullu",r:["NADPH üretilir.","Nükleotit sentezi için riboz-5-fosfat sağlar.","Hız kısıtlayıcı enzimi glukoz-6-fosfat dehidrogenazdır.","Oksidatif fazında ATP üretilir."],q:"Pentoz fosfat yolu ile ilgili yukarıdaki ifadelerden hangileri doğrudur?",o:["I ve II","II ve IV","I, III ve IV","I, II ve III","I, II, III ve IV"],a:"D",e:"Pentoz fosfat yolunda ATP ne üretilir ne tüketilir. Oksidatif fazda G6PD ile NADPH oluşur (yağ asidi ve kolesterol sentezi, glutatyonun indirgenmesi); oksidatif olmayan fazda riboz-5-fosfat elde edilir. G6PD eksikliğinde oksidan stresle hemoliz gelişir."},
/* ===== MİKROBİYOLOJİ ===== */
{t:"olumsuz",q:"Aşağıdakilerden hangisi <i>Streptococcus mutans</i>'ın çürük oluşumundaki virülans faktörlerinden biri <u>değildir</u>?",o:["Glukoziltransferaz ile sükrozdan suda çözünmeyen glukan sentezi","Düşük pH'ta yaşayabilme (asidürik özellik)","Glukan bağlayan proteinler","Laktat dehidrogenaz aracılığıyla laktik asit üretimi","Gingipain adlı sistein proteazları"],a:"E",e:"Gingipainler <i>Porphyromonas gingivalis</i>'in temel virülans faktörüdür. <i>S. mutans</i>'ın kariyojenitesi asidojenik ve asidürik olmasına, glukoziltransferazlarla glukan sentezine ve glukan bağlayan proteinlerle diş yüzeyine tutunmasına dayanır."},
{t:"vaka",q:"Diş hekimliği fakültesinde klinik eğitime başlayacak bir öğrencinin hepatit B serolojisi HBsAg (–), anti-HBs (+), anti-HBc IgG (–) olarak bulunuyor.<br><br><b>Bu sonuç için <u>en olası</u> yorum aşağıdakilerden hangisidir?</b>",o:["Akut hepatit B enfeksiyonu","Kronik hepatit B taşıyıcılığı","Geçirilmiş ve iyileşmiş enfeksiyon","Aşılama ile kazanılmış bağışıklık","Pencere dönemi"],a:"D",e:"Aşı yalnızca HBsAg içerdiğinden aşılananlarda yalnız anti-HBs pozitifleşir. Doğal enfeksiyon geçirenlerde anti-HBc de pozitiftir. Pencere döneminde HBsAg ve anti-HBs negatif, anti-HBc IgM pozitiftir. Anti-HBs ≥10 mIU/mL koruyucu kabul edilir."},
{t:"bilgi",q:"Otoklav (nemli ısı) sterilizasyonunun etkinliğini izlemek amacıyla biyolojik indikatör olarak kullanılan mikroorganizma aşağıdakilerden hangisidir?",o:["<i>Bacillus atrophaeus</i>","<i>Geobacillus stearothermophilus</i>","<i>Clostridium perfringens</i>","<i>Staphylococcus aureus</i>","<i>Pseudomonas aeruginosa</i>"],a:"B",e:"Otoklav ve hidrojen peroksit plazma sterilizasyonu için <i>G. stearothermophilus</i> sporları; kuru ısı ve etilen oksit için <i>B. atrophaeus</i> sporları kullanılır. Otoklavda standart döngü 121 °C'de 15-20 dk veya 134 °C'de 3-4 dk'dır."},
{t:"bilgi",q:"Aşağıdakilerden hangisi tip IV aşırı duyarlılık reaksiyonuna örnektir?",o:["Anafilaksi","Serum hastalığı","Nikele bağlı kontakt dermatit","Yenidoğanın hemolitik hastalığı","Arthus reaksiyonu"],a:"C",e:"Tip IV (gecikmiş, T hücre aracılı): kontakt dermatit, tüberkülin testi, granülom oluşumu. Tip I: anafilaksi, astım. Tip II: yenidoğanın hemolitik hastalığı, transfüzyon reaksiyonu. Tip III: serum hastalığı, Arthus reaksiyonu, SLE."},
{t:"vaka",q:"Ağız içinde veziküller ve ülserler ile birlikte el ayası ve ayak tabanında veziküler döküntü görülen 3 yaşındaki bir çocuk getiriliyor.<br><br><b>Bu tablodan sorumlu olması <u>en olası</u> virus aşağıdakilerden hangisidir?</b>",o:["Herpes simpleks virus tip 1","Epstein-Barr virus","Varisella-zoster virus","Coxsackievirus A16","Kızamık virusu"],a:"D",e:"El-ayak-ağız hastalığı en sık Coxsackievirus A16 ve Enterovirus A71 ile oluşur. Coxsackie A ayrıca yumuşak damak ve tonsil plikalarında veziküllerle seyreden herpanjinaya yol açar. Primer herpetik gingivostomatitte (HSV-1) yaygın dişeti tutulumu belirgindir."},
{t:"eslestirme",q:"Socransky'nin subgingival bakteri kompleksleri ile ilgili aşağıdaki eşleştirmelerden hangisi doğrudur?",o:["Kırmızı kompleks – <i>Fusobacterium nucleatum</i>","Turuncu kompleks – <i>Prevotella intermedia</i>","Sarı kompleks – <i>Porphyromonas gingivalis</i>","Mor kompleks – <i>Tannerella forsythia</i>","Yeşil kompleks – <i>Treponema denticola</i>"],a:"B",e:"Kırmızı kompleks: <i>P. gingivalis, T. forsythia, T. denticola</i>. Turuncu: <i>F. nucleatum, P. intermedia, P. nigrescens, P. micra</i>, <i>Campylobacter</i> türleri. Sarı: <i>Streptococcus</i> türleri. Mor: <i>Actinomyces odontolyticus, Veillonella parvula</i>. Yeşil: <i>Capnocytophaga</i> türleri, <i>Eikenella corrodens</i>, <i>A. actinomycetemcomitans</i> serotip a."},
/* ===== PATOLOJİ ===== */
{t:"bilgi",q:"Aşağıdaki hücresel değişikliklerden hangisi geri dönüşümsüz hücre hasarını gösterir?",o:["Karyoreksis","Hücre şişmesi","Yağlı değişiklik","Endoplazmik retikulum dilatasyonu","Plazma membranında kabarcık (bleb) oluşumu"],a:"A",e:"Geri dönüşümlü hasar: hücresel şişme, yağlı değişiklik, bleb, mikrovillus kaybı, ER dilatasyonu, ribozomların ayrılması. Geri dönüşümsüz hasar: nükleer değişiklikler (piknoz, karyoreksis, karyoliz), mitokondride amorf yoğunluklar, lizozom ve plazma membranı yırtılması."},
{t:"olumsuz",q:"Aşağıdakilerden hangisi apoptozun özelliklerinden biri <u>değildir</u>?",o:["Çevre dokuda belirgin inflamatuvar yanıt oluşması","Hücre büzülmesi","Kromatin kondansasyonu","Apoptotik cisimcik oluşumu","Kaspazların aktivasyonu"],a:"A",e:"Apoptozda membran bütünlüğü korunur ve hücre içeriği dışarı sızmaz; apoptotik cisimcikler makrofajlarca hızla fagosite edilir, inflamasyon gelişmez. Nekrozda ise membran yırtılır ve inflamasyon belirgindir."},
{t:"bilgi",q:"Aşağıdakilerden hangisi malign tümörü benign tümörden ayırmada <u>en güvenilir</u> ölçüttür?",o:["Hızlı büyüme","Tümörde nekroz bulunması","Metastaz yapması","Hücresel pleomorfizm","Kapsül bulunmaması"],a:"C",e:"Metastaz malignitenin kesin göstergesidir. Pleomorfizm, nekroz, hızlı büyüme ve kapsül yokluğu maligniteyi destekler, ancak bazı benign tümörlerde de görülebilir."},
{t:"bilgi",q:"Odontojenik keratokistin histopatolojik özelliği aşağıdakilerden hangisidir?",o:["Belirgin granüler tabakalı, kalın ortokeratinize epitel","Dalgalı parakeratinize yüzey ve palizatlanmış hiperkromatik bazal hücreler","Hayalet (gölge) hücreler ve distrofik kalsifikasyon","Epitelde Rushton cisimcikleri ve kapsülde kolesterol yarıkları","Kapsülde osteodentin ve sementikül benzeri yapılar"],a:"B",e:"OKK: 6-8 hücre kalınlığında, dalgalı parakeratinize yüzeyli, palizatlanmış hiperkromatik bazal tabakalı ince epitel; kapsülde satellit kistler bulunabilir. <i>PTCH1</i> mutasyonu ve Gorlin-Goltz sendromu ile ilişkilidir, nüks eğilimi yüksektir. Ortokeratinize odontojenik kist ayrı bir antitedir; hayalet hücreler kalsifiye odontojenik kistte, Rushton cisimcikleri radiküler kistte görülür."},
/* ===== FARMAKOLOJİ ===== */
{t:"bilgi",q:"Amid yapılı olmasına karşın ester grubu da taşıdığından büyük ölçüde plazma esterazlarıyla inaktive edilen ve tiyofen halkası içeren lokal anestezik aşağıdakilerden hangisidir?",o:["Lidokain","Mepivakain","Artikain","Bupivakain","Prilokain"],a:"C",e:"Artikainin tiyofen halkası lipid çözünürlüğünü, ester grubu hızlı inaktivasyonu (yarı ömür yaklaşık 20-30 dk) sağlar; kemik difüzyonu iyidir. Prilokain o-toluidin metabolitiyle methemoglobinemi yapabilir; bupivakain uzun etkili ve kardiyotoksisitesi en yüksek olandır."},
{t:"bilgi",q:"Varfarin kullanan bir hastaya reçete edildiğinde CYP2C9'u inhibe ederek INR'yi yükseltmesi ve kanama riskini artırması <u>en olası</u> ilaç aşağıdakilerden hangisidir?",o:["Rifampisin","Metronidazol","Karbamazepin","Fenobarbital","K vitamini"],a:"B",e:"Metronidazol (ayrıca flukonazol, klaritromisin, siprofloksasin) varfarin metabolizmasını inhibe edip etkisini artırır. Rifampisin, karbamazepin ve fenobarbital enzim indükleyicidir ve varfarin etkisini azaltır. K vitamini varfarinin antidotudur."},
{t:"bilgi",q:"Asetilsalisilik asidin düşük dozdaki antitrombosit etkisinin mekanizması aşağıdakilerden hangisidir?",o:["COX-2'nin geri dönüşümlü inhibisyonu","ADP P2Y12 reseptörünün blokajı","Glikoprotein IIb/IIIa reseptörünün blokajı","Fosfodiesteraz inhibisyonuyla trombosit cAMP düzeyinin artışı","COX-1'in geri dönüşümsüz asetilasyonuyla tromboksan A₂ sentezinin azalması"],a:"E",e:"Aspirin COX-1'i asetilleyerek kalıcı olarak inhibe eder. Çekirdeksiz trombositler yeni enzim sentezleyemediği için etki trombosit ömrü boyunca (7-10 gün) sürer. Klopidogrel P2Y12, absiksimab GP IIb/IIIa, dipiridamol ve silostazol fosfodiesteraz üzerinden etki eder."},
{t:"olumsuz",q:"Aşağıdakilerden hangisi morfinin etkilerinden biri <u>değildir</u>?",o:["Miyozis","Solunum depresyonu","Bulantı ve kusma","Diyare","Histamin salınımına bağlı kaşıntı"],a:"D",e:"Opioidler GİS motilitesini azaltarak konstipasyon yapar; konstipasyon ve miyozise tolerans gelişmez. Morfin histamin salıverip kaşıntı ve hipotansiyon yapabilir, kemoreseptör tetik bölgeyi uyararak bulantı-kusmaya yol açar."},
/* ===== TIBBİ BİYOLOJİ VE GENETİK ===== */
{t:"bilgi",q:"Ökaryotik translasyonda başlangıç kodonu ve bu kodonun kodladığı amino asit aşağıdakilerin hangisinde birlikte verilmiştir?",o:["UAA – Metiyonin","UGA – Triptofan","AUG – Lösin","GUG – Valin","AUG – Metiyonin"],a:"E",e:"Başlangıç kodonu AUG'dir; ökaryotlarda metiyonini, prokaryotlarda N-formil metiyonini kodlar. UAA, UAG ve UGA durma kodonlarıdır (mitokondride UGA triptofanı kodlar)."},
{t:"bilgi",q:"Otozomal dominant kalıtılan ve dişlerde opalesan mavi-kahverengi renk, bulbus şekilli kronlar ve oblitere pulpa odaları ile karakterize dentinogenezis imperfekta tip II'den sorumlu gen aşağıdakilerden hangisidir?",o:["<i>AMELX</i>","<i>ENAM</i>","<i>DSPP</i>","<i>MSX1</i>","<i>PAX9</i>"],a:"C",e:"Dentin sialofosfoprotein (<i>DSPP</i>) mutasyonları dentinogenezis imperfekta tip II-III ve dentin displazisi tip II'den sorumludur. <i>AMELX</i> (X'e bağlı) ve <i>ENAM</i> amelogenezis imperfekta, <i>MSX1</i> ve <i>PAX9</i> diş agenezisi (hipodonti) ile ilişkilidir."},
{t:"bilgi",q:"Hücre döngüsünde G1/S geçişini sağlamak üzere retinoblastoma (Rb) proteinini fosforile eden kompleks aşağıdakilerden hangisidir?",o:["Siklin D – CDK4/6","Siklin B – CDK1","Siklin A – CDK1","Siklin H – CDK7","Siklin C – CDK8"],a:"A",e:"Siklin D–CDK4/6 Rb'yi fosforile eder; Rb'nin bağladığı E2F serbest kalır ve S fazı genlerinin transkripsiyonu başlar. Siklin E–CDK2 geçişi tamamlar. Siklin B–CDK1 (MPF) G2/M geçişini sağlar. p16 ve p21 CDK inhibitörleridir."},
{t:"oncullu",r:["Kendi DNA'sına ve ribozomlarına sahiptir.","Mitokondriyal DNA anne yoluyla kalıtılır.","İç zarında elektron transport zinciri bulunur.","Çok uzun zincirli yağ asitlerinin β-oksidasyonu burada başlar."],q:"Mitokondri ile ilgili yukarıdaki ifadelerden hangileri doğrudur?",o:["I ve II","III ve IV","I, II ve IV","I, II, III ve IV","I, II ve III"],a:"E",e:"Çok uzun zincirli yağ asitlerinin β-oksidasyonu peroksizomda başlar (Zellweger sendromunda bozulur). Mitokondri kendi dairesel DNA'sını ve ribozomlarını taşır, maternal kalıtılır; ETZ ve ATP sentaz iç zardadır."},

/* ===== RESTORATİF ===== */
{t:"eslestirme",q:"G.V. Black sınıflamasına göre aşağıdaki kavite – sınıf eşleştirmelerinden hangisi <u>yanlıştır</u>?",o:["Alt birinci molar dişin oklüzal yüzeyindeki kavite – Sınıf I","Üst ikinci premolar dişin mezio-oklüzal kavitesi – Sınıf II","İnsizal açısı korunmuş santral kesici dişin distal yüzey kavitesi – Sınıf III","Kanin dişinin labial yüzey servikal üçte birindeki kavite – Sınıf V","Üst lateral kesici dişin palatinal pit kavitesi – Sınıf IV"],a:"E",e:"Ön dişlerin palatinal pitleri, molarların bukkal ve lingual pitleri ile oklüzal yüzeyler Sınıf I'dir. Sınıf IV, ön dişlerde insizal açıyı içeren ara yüz kavitesidir. Sınıf VI (Simon) insizal kenar veya tüberkül tepesi kavitesidir."},
{t:"bilgi",q:"ICDAS II sistemine göre, dentin görünmeksizin minede lokalize yıkım (mikrokavitasyon) bulunan bir oklüzal lezyonun kodu aşağıdakilerden hangisidir?",o:["Kod 1","Kod 2","Kod 3","Kod 4","Kod 5"],a:"C",e:"ICDAS: 0 sağlam; 1 hava ile kurutunca görülen ilk görsel değişiklik; 2 ıslak yüzeyde de görülen belirgin değişiklik; 3 dentin görünmeden lokalize mine yıkımı; 4 dentinden yansıyan koyu gölge; 5 dentinin görüldüğü belirgin kavite; 6 yüzeyin yarısından fazlasını kaplayan geniş kavite."},
{t:"bilgi",q:"Asitle pürüzlendir-yıka (etch-and-rinse) adeziv sistem kullanılırken asit uygulaması sonrasında dentinin aşırı kurutulması aşağıdakilerden hangisine yol açar?",o:["Smear tabakasının korunmasına","Kollajen ağının çökmesi ve rezin infiltrasyonunun azalmasına","Mine prizmalarının çözünmesine","Hibrit tabaka kalınlığının artmasına","Dentin tübüllerinin mineral çökeltisiyle kapanmasına"],a:"B",e:"Demineralize dentinde kollajen ağını açık tutan sudur. Aşırı kurutmada ağ çöker, primer ve bonding infiltre olamaz; hibrit tabaka zayıflar, nanosızıntı ve postoperatif hassasiyet artar. Bu yüzden nemli dentine bağlama (wet bonding) önerilir."},
{t:"bilgi",q:"Yüksek bakırlı amalgamların klinik performansının geleneksel (düşük bakırlı) amalgamlara göre daha iyi olmasının temel nedeni aşağıdakilerden hangisidir?",o:["Korozyona en yatkın γ₂ (Sn-Hg) fazının büyük ölçüde ortadan kalkması","γ₁ (Ag-Hg) fazının tamamen elimine edilmesi","Sertleşmiş yapıda civa oranının artması","Yüksek çinko içeriği nedeniyle nemden etkilenmemesi","Amorf bir yapıda sertleşmesi"],a:"A",e:"Yüksek bakırlı alaşımlarda kalay γ₂ yerine bakırla Cu₆Sn₅ (η) fazını oluşturur. γ₂ en zayıf ve korozyona en yatkın fazdır; azalması kenar kırılmalarını ve sürünmeyi (creep) azaltır."},
{t:"olumsuz",q:"Aşağıdakilerden hangisi kompozit restorasyonlarda polimerizasyon büzülme stresini azaltmaya yönelik yaklaşımlardan biri <u>değildir</u>?",o:["C-faktörü yüksek kavite tasarımının tercih edilmesi","Tabakalama (inkremental) tekniğin kullanılması","Soft-start ışık uygulaması","Akışkan kompozit veya RMCİS ile stres absorbe eden ara tabaka oluşturulması","Düşük büzülmeli monomer içeren materyallerin kullanılması"],a:"A",e:"C-faktörü bağlı yüzeylerin bağlı olmayan yüzeylere oranıdır; Sınıf I kavitede yaklaşık 5'tir ve yükseldikçe büzülme stresi artar. Tabakalama her katmanda C-faktörünü düşürür; soft-start jel noktasını geciktirerek akışa izin verir."},
{t:"vaka",q:"Gece diş sıkma alışkanlığı olan 45 yaşındaki bir hastanın alt premolar dişlerinin bukkal servikal bölgesinde keskin kenarlı, kama (V) şeklinde, çürüksüz madde kayıpları görülüyor. Hasta fırçalama alışkanlığının normal olduğunu ve asidik gıda tüketmediğini belirtiyor.<br><br><b>Bu lezyonlar için <u>en olası</u> tanı aşağıdakilerden hangisidir?</b>",o:["Erozyon","Abrazyon","Atrizyon","Abfraksiyon","Eksternal servikal rezorpsiyon"],a:"D",e:"Abfraksiyon, eksantrik oklüzal yüklerin servikalde oluşturduğu gerilme stresiyle mine prizmalarının kopmasıdır; keskin kenarlı, derin ve kama şeklindedir. Abrazyon (fırça) daha geniş ve yuvarlak, erozyon (asit) sığ, düzgün ve parlak yüzeylidir."},
{t:"oncullu",r:["Potasyum nitrat","Stronsiyum klorür","Arjinin ve kalsiyum karbonat","Okzalat tuzları"],q:"Dentin hassasiyeti tedavisinde kullanılan yukarıdaki ajanlardan hangileri dentin tübüllerini tıkayarak etki gösterir?",o:["I ve II","II, III ve IV","I ve III","I, II ve IV","I, II, III ve IV"],a:"B",e:"Potasyum nitrat K⁺ iyonlarıyla sinir lifini depolarize ederek uyarı iletimini engeller; tübülleri tıkamaz. Stronsiyum, arjinin-kalsiyum karbonat, okzalatlar, florürler, biyoaktif cam ve adeziv rezinler tübüllerdeki sıvı akışını keserek etki eder. Mekanizma Brännström'ün hidrodinamik teorisine dayanır."},
{t:"vaka",q:"Kanal tedavili ve renklenmiş üst santral kesici dişe 'walking bleach' tekniği uygulanacaktır.<br><br><b>İnvaziv servikal rezorpsiyon riskini azaltmak için aşağıdakilerden hangisi yapılmalıdır?</b>",o:["Hidrojen peroksitin ısı ile aktive edilmesi","Sodyum perboratın %30 hidrojen peroksitle karıştırılması","Pulpa odası duvarlarının fosforik asitle pürüzlendirilmesi","Beyazlatma bitiminde hemen kompozit restorasyon yapılması","Kanal dolgusunun üzerine mine-sement birleşimi hizasında yaklaşık 2 mm kalınlıkta servikal bariyer yerleştirilmesi"],a:"E",e:"Peroksitin dentin tübülleri yoluyla servikal periodontal dokuya sızması rezorpsiyonu tetikleyebilir. Kanal dolgusu mine-sement birleşiminin yaklaşık 2 mm altına kadar uzaklaştırılır ve CİS/RMCİS ile bariyer yapılır. Isı ve %30 H₂O₂ riski artırır. Kalan oksijen bağlanmayı bozduğu için restorasyon 1-2 hafta ertelenir."},
{t:"bilgi",q:"Aşağıdaki daimî dişlerden hangisinde meziopalatinal tüberkülün palatinal yüzeyinde Carabelli tüberkülü görülmesi <u>en olasıdır</u>?",o:["Üst birinci molar","Üst ikinci premolar","Alt birinci molar","Alt ikinci molar","Üst üçüncü molar"],a:"A",e:"Carabelli tüberkülü en sık üst birinci molarda (ve üst süt ikinci molarda) görülür. Alt molarların bukkal yüzeyindeki benzer yapıya protostilid denir."},
{t:"olumsuz",q:"Kendinden asitli (self-etch) adeziv sistemlerle ilgili aşağıdaki ifadelerden hangisi <u>yanlıştır</u>?",o:["Smear tabakasını uzaklaştırmadan çözerek hibrit tabakaya dahil ederler.","Ayrı bir asit uygulaması ve yıkama basamağı gerektirmezler.","Postoperatif hassasiyet riskleri asitle pürüzlendir-yıka sistemlere göre daha düşüktür.","Kesilmemiş mine üzerinde fosforik asitle pürüzlendirmeye göre daha etkili bağlantı sağlarlar.","10-MDP içeren hafif (mild) sistemler hidroksiapatitteki kalsiyumla kimyasal bağ kurabilir."],a:"D",e:"Self-etch sistemlerin pH'ı fosforik aside göre yüksek olduğundan, özellikle kesilmemiş ve prizmasız minede mikromekanik retansiyon yetersiz kalır. Bu nedenle mineye selektif fosforik asit uygulaması önerilir."},
/* ===== PROTETİK ===== */
{t:"bilgi",q:"Tam protez yapımında mandibula fizyolojik istirahat konumundayken alt ve üst kaide plakları arasında bırakılması gereken interoklüzal mesafe (serbest aralık) ortalama ne kadardır?",o:["0,5-1 mm","2-4 mm","5-7 mm","8-10 mm","10-12 mm"],a:"B",e:"İstirahat dikey boyutundan 2-4 mm çıkarılarak oklüzal dikey boyut bulunur. Serbest aralık azaltılırsa (dikey boyut artırılırsa) kaide altında ağrı, dişlerin çarpması ve kas yorgunluğu görülür; artırılırsa yüz çökük görünür ve ağız köşelerinde keilitis gelişebilir."},
{t:"vaka",q:"Alt çenede iki taraflı ikinci premolar ve molar dişleri ile sağ lateral kesici dişi eksik olan bir hasta için hareketli bölümlü protez planlanıyor.<br><br><b>Bu hastanın Applegate kurallarına göre Kennedy sınıflaması aşağıdakilerden hangisidir?</b>",o:["Sınıf I, modifikasyon 1","Sınıf I, modifikasyon 2","Sınıf II, modifikasyon 1","Sınıf III, modifikasyon 2","Sınıf IV"],a:"A",e:"Sınıflamayı en posteriordaki dişsiz alan belirler. İki taraflı serbest sonlu boşluk Sınıf I'dir; diğer dişsiz alanlar modifikasyon olarak sayılır. Sınıf IV'ün modifikasyonu olmaz. Yerine konmayacak üçüncü molarlar dikkate alınmaz."},
{t:"bilgi",q:"Serbest sonlu hareketli bölümlü protezlerde kullanılan RPI kroşe sisteminin bileşenleri aşağıdakilerin hangisinde doğru olarak verilmiştir?",o:["Distal oklüzal tırnak, mezial proksimal plak, Akers kolu","Mezial oklüzal tırnak, lingual plak, halka kroşe","Singulum tırnağı, distal proksimal plak, T-bar","Mezial oklüzal tırnak, distal proksimal plak, I-bar","Distal oklüzal tırnak, distal proksimal plak, I-bar"],a:"D",e:"RPI: Rest (mezial oklüzal tırnak), Proximal plate (dişsiz alana bakan distal rehber düzlemle temas eden proksimal plak) ve I-bar. Kaide fonksiyonda dokuya gömüldüğünde destek dişe distal yönde tork binmesini önler."},
{t:"bilgi",q:"Kondenzasyon tipi silikon ölçü maddelerinin boyutsal stabilitesinin ilave tip silikonlara göre düşük olmasının temel nedeni aşağıdakilerden hangisidir?",o:["Polimerizasyon sırasında su açığa çıkması","Hidrofilik yapıda olması","Yan ürün olarak etil alkol oluşması ve buharlaşması","Polimerizasyon sırasında hidrojen gazı açığa çıkması","Kükürt içeren bileşikler barındırması"],a:"C",e:"Kondenzasyon silikonunda yan ürün etil alkoldür; buharlaşması büzülmeye yol açar, model hemen dökülmelidir. Polisülfitte yan ürün sudur. A-silikonda yan ürün oluşmaz ama hidrojen gazı salınabildiğinden alçı dökümü yaklaşık 1 saat geciktirilir; lateks eldivendeki kükürt A-silikonun polimerizasyonunu inhibe eder."},
{t:"bilgi",q:"Monolitik zirkonya kuronun adeziv simantasyonu öncesinde iç yüzeye uygulanması <u>en uygun</u> işlem aşağıdakilerden hangisidir?",o:["%9,5 hidroflorik asit ile pürüzlendirme ve silan uygulaması","%37 fosforik asit ile pürüzlendirme","Yalnızca silan uygulaması","Elmas frezle pürüzlendirme ve ortofosforik asit uygulaması","Alüminyum oksit partikülleriyle düşük basınçta kumlama ve 10-MDP içeren primer/siman kullanımı"],a:"E",e:"Zirkonya polikristalindir, cam faz içermez; HF asitle pürüzlendirilemez ve silan bağlanmaz. Düşük basınçlı Al₂O₃ kumlama ile MDP monomeri zirkonyaya kimyasal bağlanır. Lityum disilikat gibi cam seramiklerde ise HF asit + silan uygulanır."},
{t:"bilgi",q:"Tam protez yapımında 'f' ve 'v' seslerinin telaffuzunun değerlendirilmesi aşağıdakilerden hangisinin belirlenmesinde kullanılır?",o:["Üst ön dişlerin insizal kenarlarının konumu","Konuşma sırasında en yakın dikey mesafe","Alt ön dişlerin labiolingual konumu","Posterior palatal sınırın yeri","Oklüzal düzlemin posterior eğimi"],a:"A",e:"'F' ve 'v' seslerinde üst kesicilerin insizal kenarı alt dudağın ıslak-kuru sınırına hafifçe değer; dişler fazla kısa veya palatinalde ise ses bozulur. 'S' sesi en yakın konuşma mesafesini (yaklaşık 1 mm) ve dolayısıyla dikey boyutu değerlendirmede kullanılır."},
{t:"oncullu",r:["Sigara kullanımı","Kontrolsüz diabetes mellitus","Yetersiz primer stabilite","Kumlanmış ve asitlenmiş (SLA) implant yüzeyi"],q:"Yukarıdakilerden hangileri implantların osseointegrasyonunu olumsuz yönde etkileyebilir?",o:["I ve II","II ve IV","I, III ve IV","I, II ve III","I, II, III ve IV"],a:"D",e:"Sigara ve kontrolsüz diyabet kemik iyileşmesini bozar. Yetersiz primer stabilite, eşik değeri (yaklaşık 50-150 µm) aşan mikrohareket nedeniyle fibröz kapsülleşmeye yol açar. Pürüzlendirilmiş (SLA) yüzeyler kemik-implant temasını artırır ve osseointegrasyonu hızlandırır."},
{t:"vaka",q:"Daha önce çene eklemi bölgesinde klik sesi duyduğunu belirten 28 yaşındaki bir kadın hasta, birkaç gündür ağzını tam açamadığından yakınıyor. Muayenede klik sesinin kaybolduğu, maksimum ağız açıklığının 25 mm ile sınırlı olduğu ve ağız açılırken mandibulanın sol tarafa saptığı gözleniyor.<br><br><b>Bu hasta için <u>en olası</u> tanı aşağıdakilerden hangisidir?</b>",o:["Sağ eklemde redüksiyonlu disk deplasmanı","Sol eklemde subluksasyon","Sol eklemde sınırlı ağız açıklığıyla birlikte redüksiyonsuz disk deplasmanı","Lokal miyalji","Sağ eklemde osteoartrit"],a:"C",e:"Akut redüksiyonsuz disk deplasmanında (kapalı kilit) öne yer değiştirmiş disk kondilin translasyonunu engeller; klik kaybolur, açıklık 25-30 mm'de kalır ve translasyon yapamayan eklem tarafına sapma olur. Redüksiyonlu deplasmanda resiprokal klik vardır ve açıklık normaldir."},
{t:"bilgi",q:"Doğal dişlenmede mandibulanın protrüzyon hareketi sırasında posterior dişler arasında kama şeklinde açıklık oluşmasına ne ad verilir?",o:["Bennett hareketi","Bennett açısı","Spee eğrisi","Wilson eğrisi","Christensen fenomeni"],a:"E",e:"Christensen fenomeni, protrüzyonda kondilin artiküler eminens boyunca aşağı-öne kaymasıyla posterior dişlerin ayrılmasıdır; tam protezde kompensasyon eğrisi ile dengelenir. Bennett hareketi lateral harekette çalışan taraf kondilinin lateral yer değiştirmesi, Bennett açısı dengeleyici taraf kondilinin sagittal düzlemle yaptığı açıdır."},
{t:"olumsuz",q:"Sabit bölümlü protez planlamasında destek dişlerin değerlendirilmesi ile ilgili aşağıdaki ifadelerden hangisi <u>yanlıştır</u>?",o:["Kuron-kök oranı ideal olarak 1:2 olmalı, 1:1'den az olmamalıdır.","Ante kanununa göre destek dişlerin periodontal yüzey alanı toplamı, yerine konacak dişlerinkinden az olmamalıdır.","Konik ve birleşik kökler, ayrık ve geniş köklere göre daha iyi destek sağlar.","Gövde uzunluğu iki katına çıkarsa eğilme (deflection) yaklaşık sekiz kat artar.","Labiolingual yönde geniş kesitli kökler, yuvarlak kesitli köklere göre daha dirençlidir."],a:"C",e:"Ayrık ve divergent kökler, birleşik konik köklere göre daha iyi destek sağlar. Eğilme gövde uzunluğunun küpüyle artar, gövde yüksekliğinin küpüyle azalır."},
/* ===== CERRAHİ ===== */
{t:"hesap",q:"Sistemik olarak sağlıklı, 70 kg ağırlığındaki erişkin bir hastaya %2 lidokain + 1:100.000 adrenalin içeren 1,8 mL'lik kartuşlarla anestezi uygulanacaktır.<br><br><b>Maksimum doz 7 mg/kg kabul edildiğinde uygulanabilecek <u>en fazla</u> kartuş sayısı yaklaşık kaçtır?</b>",o:["4","6","10","13","18"],a:"D",e:"%2 = 20 mg/mL; bir kartuşta 1,8 × 20 = 36 mg lidokain vardır. 70 × 7 = 490 mg (üst sınır 500 mg). 490 / 36 ≈ 13,6, yani 13 kartuş. Kardiyovasküler hastada adrenalin sınırı (0,04 mg ≈ 2 kartuş 1:100.000) ayrıca dikkate alınır."},
{t:"bilgi",q:"Aşağıdakilerden hangisi Le Fort III kırığının özelliğidir?",o:["Kırık hattının burun tabanı seviyesinden yatay olarak geçmesi","Zigomatik arkı da içerip yüz iskeletinin kafa tabanından ayrılmasına yol açması","Piramidal şekilde nazal kemik ve infraorbital kenardan geçmesi","Yalnızca alveoler çıkıntıyı ilgilendirmesi","Pterygoid çıkıntıların etkilenmemesi"],a:"B",e:"Le Fort I (Guérin): maksillanın burun tabanı üzerinden yatay kırığı. Le Fort II: piramidal; nazal kemik, medial orbita, infraorbital kenar ve zigomatikomaksiller sütür. Le Fort III: kraniofasiyal ayrılma; frontozigomatik sütür, orbita ve zigomatik ark. Üçünde de pterygoid çıkıntılar kırılır."},
{t:"vaka",q:"Panoramik radyografide alt üçüncü molar dişin kronunun tamamen ramus içinde yer aldığı ve en yüksek noktasının ikinci molar dişin servikal hattının altında bulunduğu görülüyor.<br><br><b>Bu dişin Pell-Gregory sınıflaması aşağıdakilerden hangisidir?</b>",o:["Sınıf I – Pozisyon A","Sınıf II – Pozisyon B","Sınıf III – Pozisyon C","Sınıf II – Pozisyon C","Sınıf III – Pozisyon A"],a:"C",e:"Sınıf (ramusa göre): I, ikinci molar ile ramus arasında yeterli yer; II, kronun yarısı ramusta; III, tamamı ramus içinde. Pozisyon (derinlik): A, oklüzal düzlem seviyesinde; B, oklüzal düzlem ile servikal hat arasında; C, servikal hattın altında. Zorluk III-C'ye doğru artar."},
{t:"vaka",q:"Atriyal fibrilasyon nedeniyle varfarin kullanan ve işlem günü INR değeri 2,5 olan bir hastaya tek diş çekimi planlanıyor.<br><br><b>Bu hasta için aşağıdaki yaklaşımlardan hangisi <u>uygun değildir</u>?</b>",o:["Varfarinin kesilmeden çekimin yapılması","Sokete oksitlenmiş selüloz yerleştirilmesi","Traneksamik asitli ağız gargarası önerilmesi","Soketin primer sütürlerle kapatılması","Postoperatif analjezi için ibuprofen reçete edilmesi"],a:"E",e:"INR 3,5'in altındaysa basit çekimler varfarin kesilmeden, lokal hemostatik önlemlerle yapılabilir; ilacı kesmek tromboemboli riskini artırır. NSAİİ'ler trombosit fonksiyonunu bozar ve bazıları varfarin etkisini artırır; analjezide parasetamol tercih edilir."},
{t:"vaka",q:"Diş tedavisi sırasında yaygın ürtiker, dudak ve dilde ödem, hırıltılı solunum ve hipotansiyon gelişen erişkin bir hasta var.<br><br><b>Bu hastada ilk yapılması gereken ilaç uygulaması aşağıdakilerden hangisidir?</b>",o:["200 mg hidrokortizonun intravenöz uygulanması","10 mg klorfeniraminin intramüsküler uygulanması","1 mg adrenalinin (1:10.000) subkutan uygulanması","0,5 mg adrenalinin (1:1.000 solüsyondan 0,5 mL) uyluk anterolateraline intramüsküler uygulanması","0,5 mg adrenalinin (1:1.000) hızlı intravenöz bolus uygulanması"],a:"D",e:"Anafilakside ilk ve en önemli ilaç IM adrenalindir: erişkinde 0,5 mg (1:1.000'lik solüsyondan 0,5 mL), uyluk anterolateraline; gerekirse 5 dakikada bir tekrarlanır. Antihistaminik ve kortikosteroid ikinci basamaktır. Seyreltilmemiş adrenalinin IV bolus verilmesi aritmi riski nedeniyle tehlikelidir."},
{t:"vaka",q:"Alt sol üçüncü molar dişi çekilen bir hasta, çekimden 3 gün sonra kulağa yayılan şiddetli zonklayıcı ağrı ve ağızda kötü koku şikâyetiyle başvuruyor. Muayenede soketin boş olduğu, kemik duvarlarının açıkta kaldığı, ateş ve şişlik olmadığı görülüyor.<br><br><b>Bu hasta için <u>en uygun</u> tedavi aşağıdakilerden hangisidir?</b>",o:["Soketin serum fizyolojik ile irrigasyonu ve öjenol içeren pansuman yerleştirilmesi","Soketin küretle kazınarak yeniden kanatılması","İnsizyon ve drenaj","Sekestrektomi","Hiperbarik oksijen tedavisi"],a:"A",e:"Alveolar osteit (kuru soket) fibrinolizle pıhtının erken kaybıdır ve genellikle 2-4. günlerde başlar. Tedavi palyatiftir: nazik irrigasyon, öjenollü pansuman ve analjezik. Agresif küretaj ağrıyı artırır; enfeksiyon bulgusu yoksa sistemik antibiyotik gerekmez."},
{t:"vaka",q:"Üst sağ birinci molar dişinin çekimi sonrasında yaklaşık 8 mm çapında oroantral açıklık oluştuğu tespit ediliyor. Hastada önceden sinüzit öyküsü bulunmuyor.<br><br><b>Bu hasta için <u>en uygun</u> yaklaşım aşağıdakilerden hangisidir?</b>",o:["Yalnızca pıhtının korunması ve sinüs önlemlerinin anlatılması","Caldwell-Luc operasyonu","Sinüs tabanı yükseltme (sinüs lifting) yapılması","Soketin kalıcı akrilik plakla kapatılması","Bukkal ilerletme flebi ile primer kapama yapılması"],a:"E",e:"2 mm'den küçük açıklıklar pıhtıyla kendiliğinden kapanır; orta büyüklükte açıklıklarda soket koruması, figür-8 sütür ve sinüs önlemleri yeterli olabilir. Büyük açıklıklarda bukkal ilerletme veya palatinal rotasyon flebi ile 24-48 saat içinde primer kapama yapılır; dekonjestan ve antibiyotik eklenir."},
{t:"olumsuz",q:"İnsizyonel biyopsi ile ilgili aşağıdaki ifadelerden hangisi <u>yanlıştır</u>?",o:["Tanısal değeri artırmak için örneğin lezyonun nekrotik merkezinden alınması tercih edilir.","Büyük lezyonlarda veya malignite şüphesinde kesin tedavi öncesinde tanı amacıyla yapılır.","Lezyonun temsil edici bölümüyle birlikte komşu sağlıklı dokuyu da içermelidir.","Örnek, dokunun 10-20 katı hacimde %10'luk formalin içinde gönderilir.","Elektrokoter kullanımı örnek kenarlarında termal artefakt oluşturabilir."],a:"A",e:"Nekrotik doku tanı koydurmaz. Örnek lezyonun aktif ve temsil edici kenarından, sağlam dokuyla birlikte alınmalıdır. Elektrokoter ve lazer kenarda yanık artefaktı oluşturur; neşter tercih edilir."},
{t:"vaka",q:"Osteoporoz nedeniyle 6 yıldır oral alendronat kullanan, baş-boyun bölgesine radyoterapi öyküsü olmayan 68 yaşındaki kadın hastanın alt molar çekim bölgesinde 3 aydır iyileşmeyen ekspoze nekrotik kemik, ağrı ve pürülan akıntı izleniyor. Lezyon alveoler kemik sınırları içinde kalıyor.<br><br><b>AAOMS 2022 sınıflamasına göre bu hastanın evresi aşağıdakilerden hangisidir?</b>",o:["Evre 0","Evre 1","Evre 2","Evre 3","Risk altındaki hasta"],a:"C",e:"MRONJ tanısı için antirezorptif/antianjiyojenik ilaç öyküsü, 8 haftadan uzun süren ekspoze kemik (veya kemiğe uzanan fistül) ve çeneye radyoterapi öyküsü olmaması gerekir. Evre 1: asemptomatik ekspoze kemik. Evre 2: ağrı ve enfeksiyon bulguları. Evre 3: alveoler kemiği aşan tutulum, patolojik kırık, ekstraoral fistül, oroantral ilişki veya mandibula alt kenarına/sinüs tabanına uzanan osteoliz."},
{t:"bilgi",q:"2023 ESC enfektif endokardit kılavuzuna göre yüksek riskli ve penisilin alerjisi olmayan erişkin bir hastada dental işlem öncesi önerilen profilaksi rejimi aşağıdakilerden hangisidir?",o:["İşlemden 30-60 dk önce tek doz 2 g amoksisilin (oral)","İşlemden sonra tek doz 1 g amoksisilin","İşlemden 1 gün önce başlanan, 7 gün süren 3 × 500 mg amoksisilin","İşlemden 30-60 dk önce 600 mg klindamisin","İşlemden önce 500 mg metronidazol"],a:"A",e:"Profilaksi, dişeti veya periapikal bölgenin manipülasyonunu ya da oral mukoza perforasyonunu içeren işlemlerde yüksek riskli hastalara (protez kapak, önceki endokardit, tedavi edilmemiş siyanotik doğuştan kalp hastalığı vb.) önerilir. Penisilin alerjisinde sefaleksin 2 g ya da azitromisin/klaritromisin 500 mg verilir. Klindamisin <i>C. difficile</i> riski nedeniyle artık önerilmiyor."},
/* ===== RADYOLOJİ ===== */
{t:"bilgi",q:"Röntgen tüpünde tüp voltajının (kVp) artırılması aşağıdaki sonuçlardan hangisine yol açar?",o:["Oluşan X ışınlarının ortalama enerjisi azalır.","Radyografik kontrast azalır (uzun gri skala oluşur).","Işının penetrasyon gücü azalır.","Yalnızca foton sayısı artar, foton enerjisi değişmez.","Filamentin ısısı ve salınan elektron sayısı azalır."],a:"B",e:"kVp foton enerjisini ve penetrasyonu belirler; arttıkça daha çok gri ton (uzun ölçekli, düşük kontrast) oluşur. mA ve süre (mAs) foton sayısını yani yoğunluğu belirler; enerjiyi değiştirmez."},
{t:"bilgi",q:"Aşağıdakilerden hangisi iyonlaştırıcı radyasyonun stokastik etkilerine örnektir?",o:["Radyasyon kataraktı","Radyasyona bağlı oral mukozit","Kserostomi","Tiroid kanseri","Osteoradyonekroz"],a:"D",e:"Stokastik etkilerin eşik dozu yoktur; olasılığı dozla artar, şiddeti dozdan bağımsızdır: kanser ve kalıtsal etkiler. Deterministik etkilerin (doku reaksiyonları) eşik dozu vardır ve şiddeti dozla artar: katarakt, mukozit, kserostomi, osteoradyonekroz, radyasyon çürüğü."},
{t:"vaka",q:"Üst çenede gömülü kanin dişin konumunu belirlemek için iki periapikal radyografi alınıyor. İkinci çekimde tüp meziale kaydırıldığında kaninin görüntüsünün de komşu dişlere göre meziale kaydığı görülüyor.<br><br><b>Kaninin konumu için <u>en olası</u> yorum aşağıdakilerden hangisidir?</b>",o:["Bukkalde konumlanmıştır.","Komşu dişlerle aynı düzlemdedir.","Nazal kavite tabanında konumlanmıştır.","Palatinalde konumlanmıştır.","Bu yöntemle belirlenemez."],a:"D",e:"Bukkal obje kuralına (Clark, SLOB) göre tüple aynı yönde hareket eden obje lingualde/palatinalde (Same Lingual), ters yönde hareket eden obje bukkaldedir (Opposite Buccal)."},
{t:"bilgi",q:"Panoramik radyografi çekimi sırasında hastanın başı fokal oluğun (görüntü tabakası) önünde konumlandırılırsa görüntüde aşağıdakilerden hangisi gözlenir?",o:["Ön dişler geniş ve bulanık görünür.","Oklüzal düzlem gülümseme şeklinde aşağı doğru kavislenir.","Ön dişler dar (ince) ve bulanık görünür.","Üst kesici dişlerin apeksleri üzerinde radyolusent hava bandı oluşur.","Omurga gölgesi ön bölgeye süperpoze olur."],a:"C",e:"Baş öne yerleştirildiğinde ön dişler daralır, geriye yerleştirildiğinde genişler. Çene aşağı eğikse gülümseme, yukarı kalkıksa asık surat görünümü oluşur. Dil damağa yaslanmazsa üst apekslerde hava bandı görülür; hasta dik durmazsa omurga ön bölgeye süperpoze olur."},
{t:"vaka",q:"Rutin panoramik radyografide 40 yaşındaki erkek hastanın mandibula angulus bölgesinde, mandibular kanalın altında yer alan, yuvarlak-oval, kalın sklerotik sınırlı radyolusent alan izleniyor. Hasta asemptomatik ve bölgedeki dişler vital. KIBT incelemesinde lezyonun lingual kortekste bir çöküntü şeklinde olduğu görülüyor.<br><br><b>Bu bulgular için <u>en olası</u> tanı aşağıdakilerden hangisidir?</b>",o:["Basit kemik kisti","Odontojenik keratokist","Ameloblastoma","Dentigeröz kist","Stafne kemik kavitesi"],a:"E",e:"Stafne kemik kavitesi submandibular bez dokusunun lingual kortekste oluşturduğu gelişimsel bir çöküntüdür. Tipik olarak molar-angulus bölgesinde, mandibular kanalın altında yer alır, değişmeden kalır ve tedavi gerektirmez. Odontojenik lezyonlar genellikle kanalın üzerinde, diş taşıyan bölgededir."},
{t:"vaka",q:"Orta yaşlı bir kadın hastanın alt kesici dişlerinin apikal bölgelerinde, ortası radyoopak ve çevresi ince radyolusent bir halkayla sınırlı, çok sayıda lezyon izleniyor. Dişlerin tümü vital ve asemptomatik. Hastanın 5 yıl önceki radyografisinde aynı bölgelerde yalnızca radyolusent alanlar bulunduğu öğreniliyor.<br><br><b>Bu hasta için <u>en olası</u> tanı aşağıdakilerden hangisidir?</b>",o:["Kondensing osteitis","Periapikal sementoosseöz displazi","Periapikal granülom","Sementoblastoma","Hipersementoz"],a:"B",e:"Periapikal sementoosseöz displazi en sık orta yaşlı (özellikle Afrika kökenli) kadınlarda alt ön bölgede görülür; radyolusent, mikst ve radyoopak (radyolusent haleli) evrelerden geçer. Dişler vitaldir, tedavi gerekmez. Sementoblastoma köke yapışıktır, ağrı ve kök rezorpsiyonu yapar; kondensing osteitis inflame veya nekrotik pulpalı dişte görülür."},
{t:"vaka",q:"Maksillasında yavaş büyüyen ağrısız asimetri bulunan 13 yaşındaki bir hastanın radyografisinde sınırları belirgin olmayıp çevre kemikle kaynaşan, buzlu cam görünümlü bir lezyon izleniyor. Moleküler incelemede <i>GNAS</i> mutasyonu saptanıyor.<br><br><b>Bu hasta için <u>en olası</u> tanı aşağıdakilerden hangisidir?</b>",o:["Fibröz displazi","Ossifiye fibroma","Paget hastalığı","Osteosarkom","Kerubizm"],a:"A",e:"Fibröz displazide lezyon sınırları belirsizdir, çevre kemiğe karışır ve buzlu cam görünümü tipiktir; postzigotik <i>GNAS</i> mutasyonu ile oluşur. McCune-Albright sendromunda poliostotik tutulum, café-au-lait lekeleri ve endokrinopati eşlik eder. Ossifiye fibroma iyi sınırlıdır ve çevresinden ayrılabilir."},
{t:"olumsuz",q:"Aşağıdaki lezyonlardan hangisinin radyografide multiloküler görünüm göstermesi <u>en az olasıdır</u>?",o:["Radiküler kist","Ameloblastoma","Odontojenik keratokist","Santral dev hücreli granülom","Odontojenik miksoma"],a:"A",e:"Radiküler kist, vital olmayan dişin apeksinde kortikal sınırlı uniloküler bir radyolusensidir. Ameloblastoma (sabun köpüğü, bal peteği), odontojenik miksoma (tenis raketi), santral dev hücreli granülom (ince septalı) ve büyük OKK'lar multiloküler görünebilir."},
{t:"olumsuz",q:"Diş hekimliğinde radyasyondan korunma ile ilgili aşağıdaki ifadelerden hangisi <u>yanlıştır</u>?",o:["Dikdörtgen kolimasyon, yuvarlak kolimasyona göre hasta dozunu önemli ölçüde azaltır.","F hızlı film veya dijital sensör kullanımı hasta dozunu azaltır.","Operatör tüpten en az 2 m uzakta ve primer ışın doğrultusuyla 90-135° açı yapacak şekilde durmalıdır.","Uygun durumlarda tiroid koruyucu yaka kullanılmalıdır.","Hasta reseptörü tutamıyorsa ışınlama sırasında reseptörü operatörün tutması uygundur."],a:"E",e:"Operatör hiçbir zaman reseptörü tutmamalı ve primer ışının yolunda bulunmamalıdır; gerekirse tutucu kullanılır ya da koruyucu önlük giymiş bir yakın tutar. Temel ilke ALARA/ALADA'dır."},
{t:"hesap",q:"Fokal spot ile obje arası mesafe 20 cm'den 40 cm'ye çıkarılan bir çekimde, radyografik yoğunluğun değişmemesi için başlangıçta 0,2 saniye olan ışınlama süresi kaç saniye olmalıdır?",o:["0,4","0,6","0,8","1,2","1,6"],a:"C",e:"Ters kare kanununa göre yoğunluk mesafenin karesiyle ters orantılıdır. Mesafe iki katına çıkınca yoğunluk dörtte bire düşer; bunu telafi etmek için mAs (süre) dört katına çıkarılır: 0,2 × 4 = 0,8 sn."},
/* ===== PERİODONTOLOJİ ===== */
{t:"vaka",q:"45 yaşındaki erkek hastanın periodontal muayenesinde en fazla interproksimal klinik ataşman kaybının 6 mm, maksimum sondalama derinliğinin 6 mm olduğu ve radyografik kemik kaybının kök boyunun orta üçlüsüne uzanarak %45'e ulaştığı saptanıyor. Periodontitis nedeniyle diş kaybı bulunmayan hasta günde 15 adet sigara içiyor.<br><br><b>2017 sınıflamasına göre bu hastanın tanısı aşağıdakilerden hangisidir?</b>",o:["Evre II, Derece B","Evre III, Derece B","Evre III, Derece C","Evre IV, Derece C","Evre II, Derece C"],a:"C",e:"İnterproksimal CAL ≥5 mm ve kökün orta üçlüsüne uzanan kemik kaybı Evre III'tür (diş kaybı ≤4, cep ≥6 mm). Derece için kemik kaybı yüzdesi/yaş = 45/45 = 1,0 (0,25-1,0 arası Derece B); ancak günde ≥10 sigara dereceyi C'ye yükseltir. HbA1c ≥%7,0 olan diyabet de Derece C'ye yükseltir."},
{t:"bilgi",q:"Periodontitiste kemik yıkımının düzenlenmesinde RANKL'ye bağlanarak onun RANK reseptörüne bağlanmasını engelleyen tuzak (decoy) reseptör aşağıdakilerden hangisidir?",o:["RANK","M-CSF","İnterlökin-1β","Prostaglandin E₂","Osteoprotegerin"],a:"E",e:"Osteoblast ve fibroblastlardan salınan osteoprotegerin (OPG) RANKL'yi bağlayıp osteoklastogenezi inhibe eder. Periodontitiste RANKL/OPG oranı artar. IL-1β, TNF-α ve PGE₂ RANKL ekspresyonunu artırarak yıkımı hızlandırır."},
{t:"olumsuz",q:"Aşağıdaki ilaçlardan hangisinin ilaca bağlı dişeti büyümesine neden olması <u>en az olasıdır</u>?",o:["Fenitoin","Metformin","Siklosporin A","Nifedipin","Amlodipin"],a:"B",e:"İlaca bağlı dişeti büyümesi üç grupta görülür: antikonvülzanlar (fenitoin, valproat), immünsupresifler (siklosporin) ve kalsiyum kanal blokerleri (nifedipin, amlodipin, verapamil, diltiazem). Plak kontrolü büyümenin şiddetini azaltır."},
{t:"olumsuz",q:"Gracey ve universal küretlerle ilgili aşağıdaki ifadelerden hangisi <u>yanlıştır</u>?",o:["Gracey küretlerde bıçak yüzü alt sapla 60-70° açı (offset) yapar.","Gracey küretlerde bıçağın yalnızca bir kesici kenarı kullanılır.","Universal küretlerde bıçak yüzü alt sapla 90° açı yapar.","Gracey küretler tek bir aletle ağzın tüm bölgelerine uyum sağlayacak şekilde tasarlanmıştır.","Universal küretlerde bıçağın her iki kesici kenarı da kullanılabilir."],a:"D",e:"Gracey küretler bölgeye özgüdür: 1-2 ve 3-4 ön dişler, 5-6 ön dişler ve küçük azılar, 7-8 ve 9-10 arka dişlerin bukkal-lingual yüzeyleri, 11-12 arka dişlerin mezial, 13-14 distal yüzeyleri. Ağzın tamamında kullanılabilen tasarım universal kürettir."},
{t:"oncullu",r:["HIV enfeksiyonu","Psikolojik stres ve uyku yetersizliği","Malnütrisyon","Sigara kullanımı"],q:"Yukarıdakilerden hangileri nekrotizan periodontal hastalıklar için predispozan faktörlerdir?",o:["I ve II","I, II ve III","II, III ve IV","I, III ve IV","I, II, III ve IV"],a:"E",e:"Nekrotizan gingivitis ve periodontitis konak savunmasının bozulduğu durumlarda (HIV, malnütrisyon, stres, sigara, uyku yetersizliği, önceki atak) gelişir. Tipik bulgular papil nekrozu, kanama ve ağrıdır. Ağır malnütrisyonlu çocuklarda noma gelişebilir."},
{t:"bilgi",q:"Cairo sınıflamasına göre interproksimal ataşman kaybının bulunmadığı ve interproksimal mine-sement birleşiminin klinik olarak tespit edilemediği dişeti çekilmesi aşağıdakilerden hangisidir?",o:["RT1","RT2","RT3","Miller Sınıf III","Miller Sınıf IV"],a:"A",e:"RT1: interproksimal ataşman kaybı yok; tam kök kapama beklenir. RT2: interproksimal kayıp bukkal kayıptan az veya eşit. RT3: interproksimal kayıp bukkal kayıptan fazla; tam kök kapama beklenmez. 2017 sınıflaması Cairo sistemini esas alır."},
{t:"vaka",q:"Alt birinci molar dişin muayenesinde periodontal sondun bukkal furkasyondan girip lingual furkasyondan çıkabildiği, ancak furkasyon girişinin dişetiyle örtülü olduğu ve klinik olarak görülemediği tespit ediliyor.<br><br><b>Glickman sınıflamasına göre bu furkasyon defekti aşağıdakilerden hangisidir?</b>",o:["Sınıf I","Sınıf II","Sınıf III","Sınıf IV","Hamp Derece 1"],a:"C",e:"Glickman: I, başlangıç (sond girmez); II, kül-de-sak (sond kısmen girer, karşıya geçmez); III, sond karşıya geçer ama giriş dişetiyle örtülüdür; IV, sond geçer ve giriş dışarıdan görülür. Hamp yatay ölçüme dayanır: Derece 1 <3 mm, 2 >3 mm, 3 tam geçiş."},
{t:"bilgi",q:"2017 sınıflamasına göre, önceki muayene verileri bulunmayan bir hastada peri-implantitis tanısı için gereken kriterler aşağıdakilerin hangisinde birlikte verilmiştir?",o:["Sondalamada kanama ve cep derinliği ≥4 mm","Yalnızca radyografik olarak ≥1 mm kemik kaybı","İmplant mobilitesi ve ağrı","Sondalamada kanama ve/veya süpürasyon, cep derinliği ≥6 mm ve intraosseöz kısmın en koronal noktasından ≥3 mm apikalde kemik seviyesi","Keratinize mukoza genişliğinin <2 mm olması"],a:"D",e:"Önceki verisi olan hastada peri-implantitis: BOP/süpürasyon + öncekine göre artmış cep derinliği + başlangıç remodelingini aşan kemik kaybı. Peri-implant mukozitte kanama vardır ama başlangıç remodelingi ötesinde kemik kaybı yoktur."},
{t:"bilgi",q:"Yönlendirilmiş doku rejenerasyonunda (GTR) bariyer membran kullanılmasının temel amacı aşağıdakilerden hangisidir?",o:["Epitelin apikale göçünü hızlandırarak uzun birleşim epiteli oluşturmak","Epitel ve dişeti bağ dokusu hücrelerini dışlayarak kök yüzeyinin PDL ve kemik hücrelerince kolonize edilmesini sağlamak","Kemik greftinin yerine geçerek osteoindüksiyon sağlamak","Kök yüzeyini kimyasal olarak dekontamine etmek","Flebin kanlanmasını artırmak"],a:"B",e:"Melcher'in hücre öncelik kavramına göre kök yüzeyine ilk ulaşan hücre tipi yeni ataşmanın türünü belirler. Membran hızlı çoğalan epitel ve gingival bağ dokusunu dışarıda tutarak PDL ve kemik hücrelerine zaman ve alan kazandırır; hedef yeni sement, PDL ve kemiktir."},
{t:"vaka",q:"16 yaşındaki sistemik olarak sağlıklı bir hastada, plak miktarıyla orantısız ve birinci molar ile kesici dişlerle sınırlı şiddetli ataşman ve kemik kaybı tespit ediliyor.<br><br><b>Bu tablo ile ilişkisi en iyi bilinen ve lökotoksin üreten mikroorganizma aşağıdakilerden hangisidir?</b>",o:["<i>Porphyromonas gingivalis</i>","<i>Treponema denticola</i>","<i>Fusobacterium nucleatum</i>","<i>Prevotella intermedia</i>","<i>Aggregatibacter actinomycetemcomitans</i>"],a:"E",e:"Eski adıyla lokalize agresif periodontitis, 2017 sınıflamasında molar/kesici paterni tanımlayıcısıyla periodontitis olarak sınıflandırılır. <i>A. actinomycetemcomitans</i> (özellikle yüksek lökotoksin üreten JP2 klonu) bu tablo ile ilişkilidir; lökotoksin nötrofil ve monositleri öldürür."},
/* ===== ORTODONTİ ===== */
{t:"hesap",q:"Sefalometrik analizde SNA açısı 87°, SNB açısı 80° olarak ölçülen bir hasta için aşağıdaki yorumlardan hangisi <u>en uygundur</u>?",o:["ANB 7°, mandibuler retrognatiye bağlı iskeletsel Sınıf II","ANB 7°, maksiller prognatiye bağlı iskeletsel Sınıf II","ANB 3°, iskeletsel Sınıf I","ANB –7°, iskeletsel Sınıf III","ANB 7°, bimaksiller retrognati"],a:"B",e:"ANB = SNA – SNB = 87 – 80 = 7° (normal 2±2°), yani iskeletsel Sınıf II. SNA normalin (82±2°) üzerinde, SNB normal sınırda (80±2°) olduğundan Sınıf II'nin kaynağı maksiller prognatidir. Yorumda SN eğimi ve Wits değeri de dikkate alınmalıdır."},
{t:"bilgi",q:"El-bilek radyografisinde pubertal büyüme atılımının zirvesine yaklaşıldığını gösteren en önemli bulgu aşağıdakilerden hangisidir?",o:["Distal falanks epifizlerinin diafizle tamamen kaynaşması","Radius epifizinin diafizle tamamen kaynaşması","Başparmaktaki adduktor sesamoid kemiğin ossifikasyonu","Karpal kemiklerde ossifikasyonun hiç başlamamış olması","Orta falanks epifizinin diafizden daha dar olması"],a:"C",e:"Sesamoid kemik ossifikasyonu ve orta falanks epifizinin başlıklaşması (MP3cap) pubertal atılımın zirvesine yakın döneme işaret eder. Distal falanks epifiz kaynaşması atılımın bittiğini, radius epifiz kaynaşması büyümenin sona erdiğini gösterir. Servikal vertebra maturasyonunda zirve CS3-CS4 arasındadır."},
{t:"bilgi",q:"Ortodontik tedavide bir dişin gövdesel (translasyon) hareketi için uygulanması gereken moment/kuvvet (M/F) oranı yaklaşık kaçtır?",o:["0:1 – 5:1","7:1","10:1","12:1 ve üzeri","20:1"],a:"C",e:"M/F oranı (mm): 0-5 kontrolsüz devrilme, yaklaşık 7 kontrollü devrilme, yaklaşık 10 translasyon, 12 ve üzeri kök hareketi (tork)."},
{t:"olumsuz",q:"Aşağıdakilerden hangisi ortodontik tedavide ankraj artırma amacıyla kullanılan apareylerden biri <u>değildir</u>?",o:["Transpalatal ark","Nance apareyi","Lingual ark","Hyrax tipi hızlı genişletme apareyi","Mini vida"],a:"D",e:"Hyrax tipi aparey midpalatal sütürü ayırarak maksiller genişletme yapar; ankraj amacıyla kullanılmaz. TPA, Nance apareyi ve lingual ark dişsel ankrajı artırır; mini vidalar iskeletsel (mutlak) ankraj sağlar."},
{t:"bilgi",q:"Karma dişlenme döneminde, sürmemiş daimî kanin ve premolarların meziodistal genişliklerini alt daimî kesicilerin toplam genişliğinden yararlanarak olasılık tablolarıyla (genellikle %75 düzeyi) tahmin eden yer analizi aşağıdakilerden hangisidir?",o:["Bolton analizi","Pont indeksi","Steiner analizi","Hixon-Oldfather analizi","Moyers analizi"],a:"E",e:"Moyers analizi alt kesicilerin toplam genişliğini olasılık tablolarında kullanır. Tanaka-Johnston yöntemi aynı ölçümü formülle hesaplar (alt kesici toplamının yarısı + 10,5 mm alt, + 11 mm üst). Hixon-Oldfather radyografik ölçüm kullanır; Bolton analizi alt-üst diş boyutu uyumunu değerlendirir."},
{t:"vaka",q:"8 yaşındaki bir çocukta üst sağ santral kesici dişin dişsel çapraz kapanışta olduğu, fonksiyonel kayma bulunmadığı ve dişin hareket ettirilmesi için arkta yeterli yer olduğu tespit ediliyor. İskeletsel ilişki Sınıf I.<br><br><b>Bu hasta için <u>en uygun</u> tedavi aşağıdakilerden hangisidir?</b>",o:["Yüz maskesi","Hızlı maksiller genişletme","Chincup","Z-yaylı hareketli aparey ile kesici dişin protrüze edilmesi","Frankel III fonksiyonel apareyi"],a:"D",e:"Yeterli yer ve uygun overbite varsa tek dişlik dişsel anterior çapraz kapanış Z-yaylı (çift parmak yaylı) hareketli aparey veya dil spatülüyle düzeltilir; posterior bite plane oklüzal kilidi açar. Yüz maskesi ve chincup iskeletsel Sınıf III içindir."},
{t:"olumsuz",q:"Aşağıdakilerden hangisi hızlı maksiller genişletmenin etkilerinden biri <u>değildir</u>?",o:["Orta hat diasteması oluşması","Maksillanın öne ve aşağı yer değiştirmesi","Overbite miktarının artması","Nazal hava yolu direncinin azalması","Mandibulanın saat yönünde rotasyonu ile ön yüz yüksekliğinin artması"],a:"C",e:"HMG'de maksilla aşağı-öne hareket eder, mandibula saat yönünde döner; bu yüzden overbite azalır ve ön yüz yüksekliği artar. Sütür ayrılmasının klinik işareti santral diastemadır. Nazal taban genişlediğinden hava yolu direnci azalır."},
{t:"olumsuz",q:"Aşağıdakilerden hangisi uzun süreli parmak emme alışkanlığına bağlı bulgulardan biri <u>değildir</u>?",o:["Üst kesicilerde proklinasyon","Ön açık kapanış","Posterior çapraz kapanış","Alt kesicilerde retroklinasyon","Maksiller arkın transversal yönde genişlemesi"],a:"E",e:"Parmak emmede yanak kaslarının basıncı artar ve dil aşağıda konumlanır; maksiller ark daralır, posterior çapraz kapanış gelişebilir. Üst kesiciler protrüze, alt kesiciler retrüze olur ve ön açık kapanış oluşur. Etkiler süre (günde 6 saati aşan) ve şiddete bağlıdır."},
{t:"oncullu",r:["Maksillanın öne hareketi","Mandibulanın saat yönünde rotasyonu","Üst kesicilerin proklinasyonu","Alt kesicilerin retroklinasyonu"],q:"Büyüme dönemindeki maksiller retrognatili Sınıf III bir hastada yüz maskesi tedavisi ile yukarıdakilerden hangilerinin görülmesi beklenir?",o:["I, II, III ve IV","I ve II","I, II ve III","I, III ve IV","II, III ve IV"],a:"A",e:"Yüz maskesi maksillayı öne çekerken çene ucuna binen karşı kuvvetle mandibulada saat yönünde rotasyon oluşturur. Dişsel olarak üst kesiciler protrüze, alt kesiciler retrüze olur. En iyi sonuç erken karışık dişlenmede (8-10 yaş), sıklıkla HMG ile birlikte alınır."},
{t:"bilgi",q:"Ortodontik tedavi ile rotasyonu düzeltilen dişlerde nüksün temel nedeni olan ve yeniden düzenlenmesi en uzun süren (yaklaşık bir yıl) yapı aşağıdakilerden hangisidir?",o:["Periodontal ligamentin temel lifleri","Alveoler kemik","Sement","Supraalveoler (gingival ve transseptal) lifler","Ağız mukozası"],a:"D",e:"PDL lifleri yaklaşık 3-4 ayda, gingival kollajen lifler 4-6 ayda yeniden düzenlenir; elastik supraalveoler lifler ise bir yıldan uzun süre gerilimli kalır. Rotasyon nüksünü azaltmak için çevresel supraalveoler fibrotomi (CSF) ve uzun süreli sabit retansiyon önerilir."},
/* ===== ENDODONTİ ===== */
{t:"vaka",q:"28 yaşındaki bir hasta alt sağ birinci molar dişinde gece uyutmayan ağrıdan yakınıyor. Soğuk testine şiddetli yanıt alınıyor ve ağrı uyaran kaldırıldıktan sonra 1 dakikadan uzun sürüyor. Perküsyon ve palpasyon testleri normal; radyografide periapikal bölge olağan görünümde.<br><br><b>AAE terminolojisine göre bu diş için <u>en olası</u> tanı aşağıdakilerden hangisidir?</b>",o:["Semptomatik irreversibl pulpitis, normal apikal dokular","Reversibl pulpitis, normal apikal dokular","Asemptomatik irreversibl pulpitis, normal apikal dokular","Pulpa nekrozu, semptomatik apikal periodontitis","Daha önce başlanmış tedavi, asemptomatik apikal periodontitis"],a:"A",e:"Uyaran kaldırıldıktan sonra devam eden ağrı ile spontan/gece ağrısı semptomatik irreversibl pulpitisi gösterir. Reversibl pulpitiste ağrı uyaranla başlar ve uyaran kalkınca saniyeler içinde geçer. Perküsyon normal olduğundan apikal dokular normal kabul edilir."},
{t:"bilgi",q:"Kök kanal irrigasyonu sırasında sodyum hipoklorit ile klorheksidinin karşılaşması sonucu oluşan, dentin tübüllerini tıkayan ve potansiyel olarak toksik turuncu-kahverengi çökelti aşağıdakilerden hangisidir?",o:["Kalsiyum hipoklorit","Sodyum klorür","Parakloroanilin","Klor gazı","Kalsiyum fosfat"],a:"C",e:"NaOCl ile CHX arasında serum fizyolojik, distile su veya alkolle ara yıkama yapılmalıdır. NaOCl organik doku çözücüdür; CHX substantivite gösterir ancak doku çözmez."},
{t:"olumsuz",q:"Etilendiamin tetraasetik asit (EDTA) ile ilgili aşağıdaki ifadelerden hangisi <u>yanlıştır</u>?",o:["Şelasyon yoluyla kalsiyum iyonlarını bağlar.","Smear tabakasının inorganik bileşenini uzaklaştırır.","Kök kanalında genellikle %17'lik konsantrasyonda kullanılır.","Organik doku çözme etkinliği sodyum hipokloritten fazladır.","Kalsifiye ve dar kanalların şekillendirilmesini kolaylaştırır."],a:"D",e:"EDTA organik doku çözmez; smear tabakasının inorganik kısmını uzaklaştırır. Organik kısım için NaOCl kullanılır, bu yüzden ikisi ardışık uygulanır. Uzun süreli EDTA uygulaması peritübüler dentinde erozyona yol açabilir."},
{t:"bilgi",q:"Üst birinci molar dişin giriş kavitesinde meziobukkal ikinci kanal (MB2) girişinin aranması gereken <u>en olası</u> bölge aşağıdakilerden hangisidir?",o:["Distobukkal kanal girişinin distali","Palatinal kanal girişinin distali","MB1 ile palatinal kanal girişlerini birleştiren hat üzerinde, MB1'in palatinali","Distobukkal ile palatinal kanal girişlerinin arası","Pulpa odası tabanının tam merkezi"],a:"C",e:"MB2 genellikle MB1'in 1-3 mm palatinalinde, MB1-palatinal hattı üzerinde veya bu hattın hafif mezialindedir. Görülme sıklığı %60'ın üzerindedir; magnifikasyon, ultrasonik uçlar ve KIBT bulmayı kolaylaştırır. Bunun için giriş kavitesi eşkenar dörtgen biçimine genişletilir."},
{t:"bilgi",q:"Vertucci sınıflamasına göre pulpa odasından iki ayrı kanal olarak başlayan ve apekse yakın bölgede birleşerek tek apikal foramenle sonlanan kanal konfigürasyonu aşağıdakilerden hangisidir?",o:["Tip I (1)","Tip II (2-1)","Tip III (1-2-1)","Tip IV (2-2)","Tip V (1-2)"],a:"B",e:"Vertucci: I (1), II (2-1), III (1-2-1), IV (2-2), V (1-2), VI (2-1-2), VII (1-2-1-2), VIII (3). Tip II'de kanallardan biri çalışma boyuna, diğeri birleşme noktasına kadar doldurulabilir."},
{t:"bilgi",q:"IADT 2020 rehberine göre kök gelişimini tamamlamış ve avulse olduktan sonra 15 dakika içinde olay yerinde replante edilmiş daimî bir dişte uygulanacak splint tipi ve süresi aşağıdakilerden hangisidir?",o:["Rijit splint, 4 hafta","Esnek splint, 4 hafta","Rijit splint, 2 hafta","Splint gerekmez","Esnek splint, 2 hafta"],a:"E",e:"Avülsiyonda esnek splint 2 hafta; lateral lüksasyon, intrüzyon, kök kırığı ve alveol kırığında 4 hafta (servikal üçlü kök kırığında 4 aya kadar) uygulanır. Kökü tamamlanmış avulse dişte kök kanal tedavisine replantasyondan sonraki 2 hafta içinde başlanır."},
{t:"bilgi",q:"Kurvatürlü bir kök kanalında, kanal duvarına sıkışmadan serbestçe dönen nikel-titanyum eğenin tekrarlayan gerilme-sıkışma döngüleri sonucunda kırılmasına ne ad verilir?",o:["Torsiyonel kırılma","Süperelastisite","Şekil hafızası","Siklik (döngüsel) yorgunluk","Faz dönüşümü"],a:"D",e:"Siklik yorgunluk kurvatürün en dar bölgesinde, öncesinde belirgin deformasyon olmadan oluşur. Torsiyonel kırılma ise eğenin ucu sıkışırken sapın dönmeye devam etmesiyle gelişir ve öncesinde sarmallarda açılma görülebilir. Isıl işlem görmüş alaşımlar yorgunluk direncini artırır."},
{t:"oncullu",r:["Yüksek pH'sı ile antibakteriyel etki gösterir.","<i>Enterococcus faecalis</i>'e karşı oldukça etkilidir.","Bakteriyel lipopolisakkaritleri inaktive eder.","Sodyum hipokloritin organik doku çözme etkinliğini artırır."],q:"Kanal içi medikament olarak kullanılan kalsiyum hidroksit ile ilgili yukarıdaki ifadelerden hangileri doğrudur?",o:["I ve III","I, III ve IV","II ve IV","I, II ve III","I, II, III ve IV"],a:"B",e:"Ca(OH)₂ yaklaşık 12,5 pH'ı ile hidroksil iyonları üzerinden etki eder, LPS'yi hidrolize eder ve kalan dokuyu denatüre ederek NaOCl'nin çözmesini kolaylaştırır. <i>E. faecalis</i> proton pompası sayesinde yüksek pH'a dirençlidir ve persistan enfeksiyonlarda sık bulunur."},
{t:"bilgi",q:"Periapikal cerrahide kök ucu rezeksiyonu için önerilen miktar ve kesim açısı aşağıdakilerin hangisinde birlikte verilmiştir?",o:["1 mm, 45° eğimli","3 mm, kök uzun eksenine dik veya minimal eğimli","5 mm, 45° eğimli","3 mm, 45° eğimli","6 mm, kök uzun eksenine dik"],a:"B",e:"Apikal 3 mm'nin rezeksiyonu apikal ramifikasyonların yaklaşık %98'ini, lateral kanalların %93'ünü ortadan kaldırır. Eğimli kesim açık dentin tübüllerini artırıp sızıntıya yol açtığından dik kesim önerilir. Retrograd kavite ultrasonik uçla 3 mm derinliğinde hazırlanır, MTA veya biyoseramikle doldurulur."},
{t:"vaka",q:"Üst santral kesici dişin periapikal radyografisinde kök kanalı ile devamlılık gösteren, düzgün sınırlı, simetrik, balon şeklinde radyolusent bir genişleme izleniyor. Farklı açılarla alınan radyografilerde lezyonun kök kanalıyla ilişkisinin değişmediği ve kanal duvarı sınırlarının lezyon bölgesinde izlenemediği görülüyor.<br><br><b>Bu bulgular için <u>en olası</u> tanı aşağıdakilerden hangisidir?</b>",o:["İnternal (inflamatuvar) rezorpsiyon","Eksternal servikal rezorpsiyon","Replasman rezorpsiyonu","Geçici apikal rezorpsiyon","Yüzeysel eksternal rezorpsiyon"],a:"A",e:"İnternal rezorpsiyon pulpadan kaynaklanır; açı değiştirilse de kanalla ilişkisi korunur ve kanal sınırı kaybolur. Eksternal servikal rezorpsiyonda lezyon açı değişikliğiyle kanal üzerinde yer değiştirir, kanal duvarı lezyonun içinden izlenebilir ve pulpa genellikle vitaldir."},
/* ===== ÇOCUK DİŞ HEKİMLİĞİ ===== */
{t:"hesap",q:"20 kg ağırlığındaki bir çocuğun 12,3 mg F/mL içeren %1,23'lük asidüle fosfat florür (APF) jelini yanlışlıkla yuttuğu öğreniliyor.<br><br><b>Olası toksik doz (PTD) 5 mg F/kg kabul edildiğinde, bu çocuk için acil müdahale gerektiren eşik yaklaşık kaç mL jele karşılık gelir?</b>",o:["2 mL","4 mL","8 mL","16 mL","25 mL"],a:"C",e:"PTD = 5 mg F/kg × 20 kg = 100 mg F; 100 / 12,3 ≈ 8 mL. Bu miktarın aşıldığı yutmalarda hastaneye sevk gerekir. İlk yardımda kalsiyum içeren sıvılar (süt) verilerek florür bağlanır."},
{t:"bilgi",q:"Süt dişlenmede primat (maymun) aralıklarının yerleşimi aşağıdakilerin hangisinde doğru olarak verilmiştir?",o:["Üst çenede santral-lateral, alt çenede lateral-kanin arası","Üst çenede lateral-kanin, alt çenede kanin-birinci süt molar arası","Üst çenede kanin-birinci süt molar, alt çenede lateral-kanin arası","Her iki çenede santral kesiciler arası","Her iki çenede birinci ve ikinci süt molarlar arası"],a:"B",e:"Primat aralıkları üstte lateral ile kanin arasında, altta kanin ile birinci süt molar arasındadır. Aralıklı süt dişlenmesi daimî kesicilere yer sağladığı için olumludur. Alt primat aralığı erken mezial kayma ile molar ilişkinin düzelmesine katkı verir."},
{t:"bilgi",q:"Süt dişlerinin vital pulpotomisinde klinik ve radyografik başarısı en yüksek bulunan kalsiyum silikat esaslı materyal aşağıdakilerden hangisidir?",o:["Formokrezol","Ferrik sülfat","Kalsiyum hidroksit","Çinko oksit öjenol","Mineral trioksit agregat"],a:"E",e:"Sistematik derlemelerde süt dişi pulpotomisinde MTA ve diğer biyoseramikler en yüksek başarıyı gösterir. Formokrezol karsinojenik potansiyeli nedeniyle giderek terk edilmektedir. Kalsiyum hidroksit süt dişi pulpotomisinde internal rezorpsiyon riski nedeniyle önerilmez."},
{t:"vaka",q:"Diş hekimine ilk kez getirilen 5 yaşındaki bir çocuk tedaviyi kabul etmekte isteksiz davranıyor; işbirliği yapmıyor ve belirgin olmamakla birlikte suskun, içine kapanık tavırlarla olumsuz bir tutum sergiliyor.<br><br><b>Frankl davranış derecelendirme ölçeğine göre bu çocuğun davranışı aşağıdakilerden hangisi ile tanımlanır?</b>",o:["Frankl 1 (kesinlikle negatif)","Frankl 2 (negatif)","Frankl 3 (pozitif)","Frankl 4 (kesinlikle pozitif)","Wright sınıflamasına göre işbirliğine yatkın"],a:"B",e:"Frankl 1: tedaviyi reddeder, ağlar, korkusu belirgindir. Frankl 2: isteksizdir, işbirliği yapmaz; olumsuz tutum belirgin değildir (somurtkan, içine kapanık). Frankl 3: tedaviyi kabul eder, zaman zaman temkinlidir. Frankl 4: diş hekimiyle iyi ilişki kurar, ilgilidir."},
{t:"olumsuz",q:"Erken çocukluk çağı çürükleri (EÇÇ) ile ilgili aşağıdaki ifadelerden hangisi <u>yanlıştır</u>?",o:["Altı yaş altındaki bir çocukta tek bir çürük yüzey bulunması EÇÇ tanısı için yeterli değildir.","Lezyonlar genellikle üst süt kesicilerin labial yüzeylerinde başlar.","Alt süt kesiciler dil ve tükürük bezi kanallarının koruyucu etkisiyle daha az etkilenir.","Gece biberonla şekerli içecek tüketimi risk faktörüdür.","Mutans streptokoklarının anneden bebeğe vertikal geçişi rol oynar."],a:"A",e:"AAPD tanımına göre 71 aylık veya daha küçük bir çocukta bir veya daha fazla çürük (kavitasyonlu veya kavitasyonsuz), çürük nedeniyle eksik ya da dolgulu süt dişi yüzeyi EÇÇ'dir. Üç yaş altında herhangi bir düz yüzey çürüğü şiddetli EÇÇ kabul edilir."},
{t:"vaka",q:"Sağ alt süt ikinci molar dişi derin çürük nedeniyle çekilen 4,5 yaşındaki bir çocukta daimî birinci molar dişin henüz sürmediği ve radyografide kemik içinde geliştiği görülüyor.<br><br><b>Bu çocuk için <u>en uygun</u> yer tutucu aşağıdakilerden hangisidir?</b>",o:["Bant-loop yer tutucu","Lingual ark","Nance apareyi","Distal shoe yer tutucu","Yer tutucu gerekmez, gözlem"],a:"D",e:"Distal shoe, sürmemiş daimî birinci moların meziale kaymasını önleyen bir kılavuzdur; birinci süt molardan destek alır. Bakteriyemi riski taşıyan sistemik hastalıklarda kontrendikedir. Bant-loop daimî molar sürdükten sonra kullanılır."},
{t:"vaka",q:"3 yaşındaki bir çocuğun üst süt santral kesici dişinin düşme sonucu avulse olduğu ve dişin 20 dakika sonra süt içinde getirildiği öğreniliyor.<br><br><b>IADT 2020 rehberine göre bu çocuk için <u>en uygun</u> yaklaşım aşağıdakilerden hangisidir?</b>",o:["Dişin replante edilip 2 hafta esnek splintle sabitlenmesi","Dişin replante edilmemesi ve daimî diş germi açısından klinik-radyografik takip yapılması","Dişin replante edilip kanal tedavisi uygulanması","Dişin replante edilip 4 hafta rijit splintle sabitlenmesi","Dişin serum fizyolojikte bekletildikten sonra replante edilmesi"],a:"B",e:"Avulse süt dişleri, alttaki daimî diş germine zarar verme riski nedeniyle replante edilmez. Ebeveyne yumuşak diyet, ağız hijyeni ve olası daimî diş gelişim bozuklukları hakkında bilgi verilir."},
{t:"vaka",q:"7 yaşındaki erkek çocukta çok sayıda konjenital diş eksikliği, konik şekilli kesici dişler, seyrek ve ince saçlar, sıcağa tahammülsüzlük ve terlemede azalma tespit ediliyor.<br><br><b>Bu çocuk için <u>en olası</u> tanı aşağıdakilerden hangisidir?</b>",o:["Hipohidrotik ektodermal displazi","Kleidokranial displazi","Down sendromu","Gardner sendromu","Hipofosfatazya"],a:"A",e:"Hipohidrotik ektodermal displazi çoğunlukla X'e bağlı resesif (<i>EDA</i> geni) kalıtılır: hipodonti/anodonti, konik dişler, hipotrikoz, hipohidroz (hipertermi riski). Erken yaşta hareketli protez uygulanabilir. Kleidokranial displazide ise çok sayıda süpernümerer ve gömülü diş bulunur."},
{t:"vaka",q:"4 yaşındaki bir çocukta köklerinde rezorpsiyon bulunmayan alt süt kesici dişlerin erken ve ağrısız şekilde döküldüğü, serum alkalen fosfataz düzeyinin düşük olduğu tespit ediliyor.<br><br><b>Bu çocuk için <u>en olası</u> tanı aşağıdakilerden hangisidir?</b>",o:["Hipofosfatemik raşitizm","Hipofosfatazya","Papillon-Lefèvre sendromu","Akut lösemi","Langerhans hücreli histiyositoz"],a:"B",e:"Hipofosfatazyada doku nonspesifik alkalen fosfataz (<i>ALPL</i>) eksikliğiyle sement oluşumu bozulur; dişler kökleri rezorbe olmadan erken dökülür (en sık alt süt kesiciler). D vitaminine dirençli hipofosfatemik raşitizmde ALP normal veya yüksektir; geniş pulpa odaları ve spontan apseler tipiktir."},
{t:"oncullu",r:["Çok yüzlü geniş çürükler","Pulpotomi veya pulpektomi uygulanmış süt azı dişleri","Gelişimsel mine defektleri (hipoplazi, amelogenezis imperfekta)","Genel anestezi altında tedavi edilen yüksek çürük riskli çocuklardaki küçük lezyonlar"],q:"Yukarıdakilerden hangileri süt azı dişlerinde paslanmaz çelik kuron endikasyonları arasındadır?",o:["I ve II","I, II ve III","II ve IV","I, III ve IV","I, II, III ve IV"],a:"E",e:"AAPD'ye göre paslanmaz çelik kuronlar geniş/çok yüzlü çürüklerde, pulpa tedavisi sonrasında, gelişimsel defektlerde, kırık dişlerde ve tekrar tedavi riskinin yüksek olduğu durumlarda (ör. genel anestezi altında yüksek çürük riskli çocuklar) endikedir. Hall tekniğiyle preparasyonsuz da uygulanabilir."}
]
};
